import type { ConversionEngine, ConversionOption } from '../../shared/conversion-contracts';

export type ProviderInput = {
  path: string;
  name: string;
  extension: string;
  bytes: number;
};
export type ProviderOutput = {
  /** A basename generated by this adapter inside outputDirectory, never a user path. */
  storageName: string;
  name: string;
  mime: string;
  bytes: number;
};
export type ProviderContext = {
  signal: AbortSignal;
  maxOutputBytes: number;
  maxOutputFiles: number;
  onStage: (message: string) => Promise<void>;
  /** Recheck shared disk capacity before each output chunk is written. */
  beforeWrite?: (bytes: number) => Promise<void>;
};
export interface ConversionProvider {
  readonly id: ConversionEngine;
  readonly configured: boolean;
  health(signal: AbortSignal): Promise<void>;
  options(extension: string, signal: AbortSignal): Promise<ConversionOption[]>;
  convert(input: ProviderInput, format: string, outputDirectory: string, context: ProviderContext): Promise<ProviderOutput[]>;
}

export class ConversionProviderError extends Error {
  constructor(message: string, public readonly code = 'CONVERSION_FAILED') {
    super(message);
    this.name = 'ConversionProviderError';
  }
}
